import {escapeHtml as e,fmt} from './core.js';
import {barChart,donutChart,orderStatusRows,orderValueByRestaurant} from './charts.js';
export const supplierPages={home:['Overview','home'],restaurants:['Restaurants','users'],orders:['Orders','bag'],deliveries:['Deliveries','box'],workspace:['Workspace','settings']};
export const supplierMoney=(n,currency='USD')=>new Intl.NumberFormat('en-US',{style:'currency',currency}).format(Number(n)||0);
const status=s=>String(s).replaceAll('_',' ').replace(/^./,x=>x.toUpperCase());
const tag=s=>`<span class="tag ${s==='accepted'||s==='received'?'good':s==='pending'||s==='partially_received'?'warning':''}">${e(status(s))}</span>`;
const date=v=>v?new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'America/New_York'}).format(new Date(v.length===10?v+'T12:00:00Z':v)):'Not set';
const head=(title,text,action='')=>`<div class="page-heading"><div><h1>${e(title)}</h1><p>${e(text)}</p></div>${action}</div>`;
export function supplierContent(s){
 const p=s.supplierSnapshot;if(!p)return '<div class="empty"><h2>No supplier data loaded</h2><p>Use Refresh to try again.</p></div>';
 const connections=p.connections||[],orders=p.orders||[],deliveries=p.deliveries||[];
 const shownOrders=orders.filter(o=>(!s.supplierRestaurant||o.restaurant_id===s.supplierRestaurant)&&`${o.order_number} ${o.restaurant_name}`.toLowerCase().includes(s.search.toLowerCase()));
 if(s.page==='home'){
  const currencies=[...new Set(orders.map(o=>o.currency))].sort();if(!currencies.length)currencies.push('USD');
  const currency=currencies.includes(s.chartCurrency)?s.chartCurrency:currencies[0];
  const active=connections.filter(c=>c.status==='accepted'),open=orders.filter(o=>['ordered','partially_received'].includes(o.status));
  return `${head('Good connections. Better deliveries.','Your restaurant relationships, purchase orders, and confirmed receipts in one place.')}<div class="hero supplier-hero"><div><span class="eyebrow">SUPPLIER WORKSPACE</span><h2>Keep every restaurant<br>on the same page.</h2><p>See what your customers have ordered and which deliveries they have received.</p></div><div class="hero-symbol" aria-hidden="true">↗</div></div><div class="stats">${[['Connected restaurants',active.length],['Open orders',open.length],['Confirmed deliveries',deliveries.length],['Connection requests',connections.filter(c=>c.status==='pending').length]].map(([label,n])=>`<div class="stat"><span>${label}</span><strong class="number">${n}</strong></div>`).join('')}</div><div class="charts-grid">${donutChart('Order progress','Number of your orders by current status · all loaded orders',orderStatusRows(orders))}<div><div class="chart-control"><label>Order currency <select id="supplier-currency" aria-label="Order currency">${currencies.map(c=>`<option ${currency===c?'selected':''}>${e(c)}</option>`).join('')}</select></label></div>${barChart('Orders by restaurant',`Recorded order value · ${currency} · cancelled orders excluded`,orderValueByRestaurant(orders,currency),{unit:currency})}</div></div><section class="panel"><div class="panel-header"><h2>Orders to follow up</h2><a href="#/orders">View all orders →</a></div>${supplierOrdersTable(open)}</section>`;
 }
 if(s.page==='restaurants')return `${head('Your restaurant connections','Review connection requests and see the restaurants working with your business.')}<div class="supplier-grid">${connections.length?connections.map(c=>`<article class="panel supplier-card"><div class="row spread"><h2>${e(c.restaurant_name)}</h2>${tag(c.status)}</div><p style="margin-top:14px">${e(c.currency)} · ${c.status==='accepted'?'Connected through':'Request from'} a restaurant-approved supplier record</p><div class="supplier-footer">${c.status==='accepted'?`<span>${orders.filter(o=>o.restaurant_id===c.restaurant_id).length} orders</span><button class="btn small" data-action="supplier-orders" data-id="${e(c.restaurant_id)}">View orders →</button>`:c.status==='pending'?`<button class="btn primary small" data-action="supplier-accept" data-id="${e(c.id)}">Accept connection</button><button class="btn small" data-action="supplier-decline" data-id="${e(c.id)}">Decline</button>`:'<span class="muted">No order access</span>'}</div></article>`).join(''):'<div class="panel panel-body"><h2>No connections yet</h2><p>Share your connection code from Workspace with a restaurant owner. Their request will appear here for you to accept.</p></div>'}</div>`;
 if(s.page==='orders')return `${head('Orders from your restaurants','Only orders placed with your business appear here.')}<div class="toolbar"><input id="page-search" aria-label="Search orders or restaurants" placeholder="Search orders or restaurants" value="${e(s.search)}"><select id="supplier-restaurant" aria-label="Filter by restaurant"><option value="">All connected restaurants</option>${connections.filter(c=>c.status==='accepted').map(c=>`<option value="${e(c.restaurant_id)}" ${s.supplierRestaurant===c.restaurant_id?'selected':''}>${e(c.restaurant_name)}</option>`).join('')}</select></div><div class="panel">${supplierOrdersTable(shownOrders)}</div><p class="subtle-note">Receipts are confirmed by the restaurant. Delivery quantities are shown in each ordered product’s base unit.</p>`;
 if(s.page==='deliveries')return `${head('Delivery confirmations','Receipts recorded by your connected restaurants.')}<div class="panel"><div class="table-wrap"><table><thead><tr><th>Received</th><th>Restaurant</th><th>Order</th><th>Products received</th></tr></thead><tbody>${deliveries.map(d=>`<tr><td>${date(d.received_at)}</td><td>${e(d.restaurant_name)}</td><td>${e(d.order_number)}</td><td>${d.lines.map(l=>`${e(l.product_name)}: ${fmt(l.quantity_received)} ${e(l.base_unit)}`).join('<br>')}</td></tr>`).join('')||'<tr><td colspan="4">No confirmed deliveries yet.</td></tr>'}</tbody></table></div></div>`;
 return `${head('Your supplier workspace','Manage your supplier businesses and their restaurant connections.',s.demo?'<button class="btn primary" disabled title="Sign in to create a supplier">+ Create another supplier</button>':'<button class="btn primary" data-action="new-supplier-account">+ Create another supplier</button>')}<div class="info-grid supplier-workspace-grid"><section class="panel"><div class="panel-header"><h2>${e(p.account.name)}</h2><span class="tag">${s.demo?'Sample':'Live data'}</span></div><div class="panel-body"><label class="field">Connection code<input value="${e(p.account.id)}" readonly aria-label="Supplier connection code"></label><p>This code identifies this supplier business; it is not a password. Share it with a restaurant owner so they can request a connection from their Suppliers page. Review and accept requests in Restaurants.</p></div></section><section class="panel"><div class="panel-header"><h2>Your supplier businesses</h2><span class="tag">${s.demo?'Read-only preview':'Member access'}</span></div><div class="panel-body"><p>Use the supplier selector at the top of the page to switch between your businesses. Each supplier has its own connection code, restaurant connections, orders, and delivery records.</p><p style="margin-top:15px">${s.demo?'Sign in to create and manage real supplier businesses.':'Creating another supplier opens a separate, empty workspace. Existing connections and orders stay with their current supplier.'}</p></div></section></div><section class="panel section-gap"><div class="panel-header"><h2>What your workspace includes</h2></div><div class="panel-body"><p>Your portal shows connected restaurant names and your own orders and receipts. Restaurants’ internal inventory, usage, waste, and other supplier records are private.</p></div></section>`;
}
export function supplierOrdersTable(orders){return `<div class="table-wrap"><table><thead><tr><th>Order</th><th>Restaurant</th><th>Expected</th><th>Status</th><th>Order value</th><th></th></tr></thead><tbody>${orders.map(o=>`<tr><td><strong>${e(o.order_number)}</strong><small>${date(o.ordered_at)}</small></td><td>${e(o.restaurant_name)}</td><td>${date(o.expected_on)}</td><td>${tag(o.status)}</td><td>${supplierMoney(o.total_amount,o.currency)}</td><td><button class="btn small" data-action="supplier-order" data-id="${e(o.id)}">View order</button></td></tr>`).join('')||'<tr><td colspan="6">No orders to show yet.</td></tr>'}</tbody></table></div>`;}
export function supplierOrderBody(p,id){const o=p.orders.find(o=>o.id===id);if(!o)return null;return {title:o.order_number,subtitle:`${o.restaurant_name} · ${status(o.status)}`,body:`<div class="dialog-body"><div class="table-wrap"><table><thead><tr><th>Product</th><th>Ordered</th><th>Received</th><th>Outstanding</th><th>Unit price</th></tr></thead><tbody>${p.lines.filter(l=>l.order_id===id).map(l=>`<tr><td>${e(l.product_name)}</td><td>${fmt(l.quantity_ordered)} ${e(l.base_unit)}</td><td>${fmt(l.quantity_received)} ${e(l.base_unit)}</td><td>${o.status==='cancelled'?'Cancelled':fmt(l.quantity_outstanding)+' '+e(l.base_unit)}</td><td>${supplierMoney(l.unit_price,o.currency)}</td></tr>`).join('')}</tbody></table></div><p class="subtle-note">These are order and receipt quantities, not the restaurant’s current stock.</p></div>`};}

export function preferredSupplierAccount(accounts,{preferredId,currentId,savedId}={}){
 for(const id of [preferredId,currentId,savedId]){const account=accounts.find(a=>a.id===id);if(account)return account;}
 return accounts[0]||null;
}
export function supplierBusinessName(value){
 const name=String(value||'').trim();
 if(!name)throw new Error('Enter your business name.');
 if(name.length>160)throw new Error('Use a business name of 160 characters or fewer.');
 return name;
}
